import type { AuthoredQuestion, AuthoredText, LanguagePair, LibrarySubject } from "./question-bank.js";
import type { QuizVisual } from "./quiz.js";

function q(id: string, subject: LibrarySubject, level: AuthoredQuestion["level"], goal: LanguagePair,
  en: AuthoredText, nb: AuthoredText, visual?: readonly [QuizVisual, QuizVisual]): AuthoredQuestion {
  return { id, subject, level, goal, text: [en, nb], ...(visual ? { visual } : {}) };
}

